function u(){return{completedStepIds:[],currentStepIndex:0}}function d(t,e){return e?`${t}::${e}`:t}function i(t,e){return t.completedStepIds.includes(e)}function c(t,e){const r=new Set(t.completedStepIds);return e.steps.reduce((n,s)=>r.has(s.id)?n+1:n,0)}function p(t,e){return e.steps.length>0&&c(t,e)===e.steps.length}function o(t,e){const r=new Set(t.completedStepIds),n=e.steps.findIndex(s=>!r.has(s.id));return n>=0?n:Math.max(0,e.steps.length-1)}function f(t,e){return e.steps.length===0?0:Math.round(c(t,e)/e.steps.length*100)}function a(t,e){const r=t.completedStepIds.includes(e);return{...t,completedStepIds:r?t.completedStepIds.filter(n=>n!==e):[...t.completedStepIds,e]}}function l(t,e){return e<=0?0:Math.min(Math.max(0,t),e-1)}function S(t,e,r=!1){if(!t.includes(":projectId"))return t;if(e)return t.replace(":projectId",e);if(r)return"/projects";const n=t.replace(/^\/projects\/:projectId/,"");return n===""?"/":n.startsWith("/")?n:`/${n}`}export{d as a,l as b,c,i as d,u as e,p as i,o as n,f as p,S as r,a as t};
